import 'package:flutter/material.dart';
import 'package:stream_chat_flutter_core/stream_chat_flutter_core.dart';

void main() => runApp(MyApp());

class MyApp extends StatelessWidget {
  final client = StreamChatClient('YOUR_API_KEY');

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: StreamChatCore(client: client, child: ChannelListPage()),
    );
  }
}

class ChannelListPage extends StatelessWidget {
  final controller = StreamChannelListController();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Channels')),
      body: PagedValueListenableBuilder(
        controller: controller,
        builder: (context, channels, _) => ListView.builder(
          itemCount: channels.length,
          itemBuilder: (_, i) => ListTile(title: Text(channels[i].name ?? 'Unnamed')),
        ),
      ),
    );
  }
}
